import {themes,bookById,gospels} from './catalog.js';
import {generatePlan,validatePlan,estimateDays,totalReadings,today,dateAt,readingLabel,completionKey,weekend} from './plan.js';
import {exportBackup,importBackup,preparePdf,createPlanPdf,downloadBytes} from './portable.js';

const ICON={book:'<path d="M3 5.5C7 4 10 4 12 6c2-2 5-2 9-.5v14c-4-1.5-7-1.5-9 .5-2-2-5-2-9-.5z"/><path d="M12 6v14"/>',day:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="currentColor" stroke="none"/><circle cx="16" cy="12" r="2" fill="currentColor" stroke="none"/><circle cx="10" cy="18" r="2" fill="currentColor" stroke="none"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',left:'<path d="m14 5-7 7 7 7"/>',right:'<path d="m10 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',circle:'<circle cx="12" cy="12" r="9"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',spark:'<path d="m12 2 1.6 6.4L20 10l-6.4 1.6L12 18l-1.6-6.4L4 10l6.4-1.6zM20 18l.5 1.5L22 20l-1.5.5L20 22l-.5-1.5L18 20l1.5-.5z"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M4 13v7h16v-7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.85" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICON[name]||ICON.book}</svg>`;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ACCENTS={bosque:['Bosque','#176b50','#8ddbb9'],cielo:['Cielo','#0077b6','#71d2ff'],lumbre:['Lumbre','#c54800','#ffb68a'],anil:['Añil','#3547a8','#bac3ff'],mango:['Mango','#8a5900','#ffba47'],fucsia:['Fucsia','#a10069','#ffafd7']};
const VERSIONS={RVC:['Reina Valera Contemporánea',146],NTV:['Nueva Traducción Viviente',127],TLAI:['Traducción al Lenguaje Actual Interconfesional',178],PDT:['Palabra de Dios para Todos',197],NBV:['Nueva Biblia Viva',753],CUSTOM:['Personalizado · mi versión en YouVersion',0]};
function detectPlatform(){const os=navigator.userAgentData?.platform||navigator.platform||navigator.userAgent||'';if(/Win/i.test(os))return 'windows';if(/Mac|iPad|iPhone|iPod/i.test(os))return 'apple';return 'web';}
const previewPlatform=/^(localhost|127\.0\.0\.1)$/.test(location.hostname)?new URLSearchParams(location.search).get('preview-platform'):null;
document.documentElement.dataset.platform=['windows','apple'].includes(previewPlatform)?previewPlatform:detectPlatform();
const STORE='senda.web.v2';
const defaults={plan:null,completed:[],version:'RVC',accent:'cielo',mode:'system',size:'normal',background:false,variant:0};
let saved={};try{saved=JSON.parse(localStorage.getItem(STORE)||'{}');if(saved.plan)validatePlan(saved.plan);}catch{saved={};}
const state={...defaults,...saved,completed:new Set(Array.isArray(saved.completed)?saved.completed:[]),tab:'day',date:today(),month:today().slice(0,7),dialog:null,error:'',toast:'',generating:false,selectingDays:false,selectedDates:new Set()};
function persist(){try{localStorage.setItem(STORE,JSON.stringify({...state,completed:[...state.completed],tab:undefined,date:undefined,month:undefined,dialog:undefined,error:undefined,toast:undefined,selectingDays:undefined,selectedDates:undefined}));return true;}catch{message('No se pudo guardar en este navegador. Exporta tu plan .senda.');return false;}}
function message(text){state.toast=text;render();setTimeout(()=>{if(state.toast===text){state.toast='';render();}},3800);}
const titleTheme=id=>themes.find(t=>t[0]===id)?.[1]||'Lectura bíblica';
const dateLong=s=>{const d=new Date(s+'T12:00:00Z');return new Intl.DateTimeFormat('es',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(d);};
const dateShort=s=>{const d=new Date(s+'T12:00:00Z');return new Intl.DateTimeFormat('es',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(d);};
const nameMonth=s=>{const d=new Date(s+'-01T12:00:00Z');return new Intl.DateTimeFormat('es',{month:'long',year:'numeric',timeZone:'UTC'}).format(d);};
const monthOffset=(s,delta)=>{const [y,m]=s.split('-').map(Number);return new Date(Date.UTC(y,m-1+delta,1)).toISOString().slice(0,7);};
const planDay=s=>state.plan?.days.find(day=>day.date===s);
function progress(){const plan=state.plan,all=plan?.days.reduce((n,d)=>n+d.readings.length,0)||0;let complete=0,partial=0,unread=0;for(const d of plan?.days||[]){const count=d.readings.reduce((n,_,i)=>n+Number(state.completed.has(completionKey(d.date,i))),0);if(count===d.readings.length)complete++;else if(count)partial++;else unread++;}return {total:all,done:state.completed.size,complete,partial,unread,percent:all?Math.round(state.completed.size/all*100):0};}
function applyAppearance(){const root=document.documentElement,p=ACCENTS[state.accent]||ACCENTS.cielo;root.dataset.mode=state.mode;root.dataset.size=state.size;const dark=state.mode==='dark'||state.mode==='system'&&matchMedia('(prefers-color-scheme: dark)').matches;root.style.setProperty('--accent',dark?p[2]:p[1]);const color=root.dataset.platform==='apple'?(dark?'#111317':'#f5f5f7'):root.dataset.platform==='windows'?(dark?'#1b2028':'#f1f4f8'):(dark?'#101b20':'#f4f7f8');document.querySelector('meta[name="theme-color"]').content=color;}
function bibleUrl(r,version){const chosen=bookById[r.book]?.dc?'TLAI':version;if(chosen==='CUSTOM')return `https://www.bible.com/es/bible?reference=${r.book}.${r.chapter}.1`;const [,id]=VERSIONS[chosen]||VERSIONS.RVC;return `https://www.bible.com/es/bible/${id}/${r.book}.${r.chapter}.${chosen}`;}
function openYouVersionOnApple(event,target,date,index){const apple=/iPad|iPhone|iPod/.test(navigator.userAgent)||/Macintosh/.test(navigator.userAgent)&&navigator.maxTouchPoints>1;if(!apple)return;const r=planDay(date)?.readings[index];if(!r)return;event.preventDefault();const version=bookById[r.book]?.dc?'TLAI':target.dataset.version||state.version;const scheme=`youversion://bible?reference=${r.book}.${r.chapter}.1${version==='CUSTOM'?'':`&version=${version}`}`;let left=false;const onVisibility=()=>{if(document.visibilityState==='hidden')left=true;};document.addEventListener('visibilitychange',onVisibility);try{window.location.href=scheme;}catch{document.removeEventListener('visibilitychange',onVisibility);window.location.href=target.href;return;}setTimeout(()=>{document.removeEventListener('visibilitychange',onVisibility);if(!left&&document.visibilityState==='visible')window.location.href=target.href;},1200);}
function nav(){const items=[['day','Día','day'],['month','Mes','calendar'],['advanced','Avanzado','settings']];return `<nav class="rail-nav" aria-label="Menú principal">${items.map(([id,label,glyph])=>`<button class="nav-button ${state.tab===id?'active':''}" data-tab="${id}" aria-current="${state.tab===id?'page':'false'}">${icon(glyph)}${label}</button>`).join('')}</nav>`;}
function shell(content){
 const hasPlan=!!state.plan&&today()<=state.plan.days.at(-1).date;
 const bottomNav=hasPlan?`<nav class="mobile-nav" aria-label="Menú inferior">${[['day','Día','day'],['month','Mes','calendar'],['advanced','Avanzado','settings']].map(([id,label,glyph])=>`<button data-tab="${id}" class="${state.tab===id?'active':''}" aria-current="${state.tab===id?'page':'false'}">${icon(glyph)}${label}</button>`).join('')}</nav>`:'';
 return `<a class="skip" href="#main">Ir al contenido</a><div class="app ${hasPlan?'':'no-plan'}"><aside class="rail"><a class="brand" href="/" aria-label="Senda, inicio"><span class="brand-mark">${icon('book')}</span>Senda</a>${hasPlan?nav():''}${hasPlan?'<div class="rail-bottom">Tu recorrido queda en este dispositivo.<br>Guarda una copia .senda para llevarlo contigo.</div>':''}</aside><div><header class="mobile-top"><span class="brand"><span class="brand-mark">${icon('book')}</span>Senda</span><button class="icon-button" data-action="show-install" aria-label="Instalar Senda">${icon('download')}</button></header><main class="main" id="main"><div class="topline"><span class="eyebrow">TU CAMINO EN LA PALABRA</span><div class="head-actions"><span class="topdate">${escape(dateShort(today()))}</span></div></div>${content}</main></div></div>${bottomNav}${dialog()}${state.toast?`<div class="toast" role="status">${escape(state.toast)}</div>`:''}`;
}
function selectField(id,label,value,options){return `<div class="field"><label for="${id}">${label}</label><select class="select" id="${id}" data-field="${id}">${options.map(([key,name])=>`<option value="${escape(key)}" ${key===value?'selected':''}>${escape(name)}</option>`).join('')}</select></div>`;}
function rangeField(id,label,value,min,max){return `<div class="field"><div class="range-row"><label for="${id}">${label}</label><span class="range-value" id="${id}-value">${value}</span><input id="${id}" data-field="${id}" type="range" min="${min}" max="${max}" step="1" value="${value}"></div></div>`;}
function toggleField(id,title,hint,checked){return `<label class="toggle-row" for="${id}"><span><strong>${title}</strong><span>${hint}</span></span><input id="${id}" data-field="${id}" type="checkbox" ${checked?'checked':''}></label>`;}
let draft={theme:'faith',dc:true,weekdayChapters:3,weekendChapters:2,repeatPsalms:true,proverbCycles:4,repeatGospels:true};
function generatePlanAsync(start,theme,dc,prefs){if(!('Worker' in window))return Promise.resolve(generatePlan(start,theme,dc,prefs));return new Promise((resolve,reject)=>{const worker=new Worker('./generator.worker.js',{type:'module'});const timer=setTimeout(()=>{worker.terminate();reject(Error('La generación tardó demasiado. Inténtalo de nuevo.'));},120000);worker.onmessage=event=>{clearTimeout(timer);worker.terminate();event.data.error?reject(Error(event.data.error)):resolve(event.data.plan);};worker.onerror=()=>{clearTimeout(timer);worker.terminate();reject(Error('No se pudo ejecutar el generador.'));};worker.postMessage({start,theme,dc,prefs});});}
function cachePdfForDownload(data,name){const worker=navigator.serviceWorker?.controller;if(!worker||!('MessageChannel'in window))return Promise.resolve(null);return new Promise(resolve=>{const channel=new MessageChannel();const timer=setTimeout(()=>resolve(null),3000);channel.port1.onmessage=event=>{clearTimeout(timer);resolve(event.data?.ok?'/__senda_plan.pdf':null);};try{worker.postMessage({type:'prepare-pdf',bytes:data,name},[channel.port2]);}catch{clearTimeout(timer);resolve(null);}});}
function onboarding(){const estimated=estimateDays(today(),draft.dc,draft),finish=dateAt(today(),estimated-1),total=totalReadings(draft.dc,draft);return `<section class="intro"><div class="intro-head"><span class="eyebrow">NUEVO RECORRIDO</span><h1>La Palabra, a tu ritmo.</h1><p>Comienza un nuevo plan el día de hoy y lee la Biblia entera. Tú decides la cantidad de capítulos; Senda organiza el camino.</p></div><div class="intro-grid"><form class="card flat" id="new-plan"><h2>Tu plan comienza aquí</h2><p class="quiet">Ajusta tus lecturas y conoce la fecha estimada antes de empezar.</p>${selectField('theme','¿Qué deseas profundizar?',draft.theme,themes.map(t=>[t[0],t[1]]))}<p class="hint">Escoge una temática y tu lectura diaria se enfocará en tu elección.</p><h3 class="group-title">¿Cuánto deseas leer?</h3>${rangeField('weekdayChapters','Capítulos en días de semana',draft.weekdayChapters,1,4)}${rangeField('weekendChapters','Capítulos en fin de semana',draft.weekendChapters,1,3)}${toggleField('dc','Lecturas deuterocanónicas','Tobías, Sabiduría y otros libros adicionales.',draft.dc)}${toggleField('repeatPsalms','Repetir Salmos','Dos recorridos en distinto orden.',draft.repeatPsalms)}${toggleField('repeatGospels','Repetir Evangelios','Dos recorridos; el segundo por etapas del ministerio de Jesús.',draft.repeatGospels)}${selectField('proverbCycles','Veces que deseas leer Proverbios',String(draft.proverbCycles),[1,2,3,4].map(n=>[String(n),`${n} ${n===1?'vez':'veces'}`]))}${selectField('version','Traducción preferida',state.version,Object.entries(VERSIONS).map(([id,[name]])=>[id,`${id==='CUSTOM'?'':id+' · '}${name}`]))}<div class="notice"><strong>Un recorrido hecho para ti</strong><br><span id="estimate">${total} capítulos · cerca de ${estimated} días · hasta ${dateShort(finish)}</span></div><div class="button-row" style="margin-top:1.2rem"><button type="submit" class="button primary" ${state.generating?'disabled':''}>${state.generating?'Organizando tus lecturas…':'Crear mi plan ahora'} ${icon('arrow')}</button><label class="button outline file-button">${icon('share')} Restaurar .senda<input type="file" accept=".senda,application/vnd.senda.plan" data-action="import" aria-label="Restaurar respaldo .senda"></label></div><p class="check-status">Sin cuenta. Tu plan y progreso se guardan en este dispositivo.</p>${state.error?`<p class="error" role="alert">${escape(state.error)}</p>`:''}</form><div class="intro-preview" style="background-image:url('./images/theme_${draft.theme}.webp')"><span class="eyebrow" style="color:#ccecff">SENDA</span><h2>${escape(titleTheme(draft.theme))}</h2><p>Un día a la vez. Un camino propio.</p></div></div></section>`;}
function readStatus(day){const n=day.readings.filter((_,i)=>state.completed.has(completionKey(day.date,i))).length;return n===0?'none':n===day.readings.length?'complete':'partial';}
function dayCard(day){const n=day.readings.filter((_,i)=>state.completed.has(completionKey(day.date,i))).length;return `<section class="card"><div class="section-head"><div><span class="eyebrow">LECTURAS DE ESTE DÍA</span><h2>${n} de ${day.readings.length} capítulos leídos</h2></div><span class="quiet">${escape(titleTheme(day.focus))}</span></div><div class="reading-list">${day.readings.map((r,i)=>{const done=state.completed.has(completionKey(day.date,i)),dc=bookById[r.book]?.dc;return `<article class="reading ${done?'done':''}"><div><div class="reading-title">${escape(readingLabel(r))}</div><div class="reading-sub">${dc?'Deuterocanónico · TLAI':gospels.has(r.book)?'Evangelio':r.book==='PSA'||r.book==='PRO'?`Ciclo ${r.cycle}`:bookById[r.book].testament==='N'?'Nuevo Testamento':'Antiguo Testamento'}</div></div><button class="reading-check" data-action="toggle-reading" data-date="${day.date}" data-index="${i}" aria-pressed="${done}" aria-label="${done?'Marcar como pendiente':'Marcar como completada'}: ${escape(readingLabel(r))}">${icon(done?'check':'circle')}</button><div class="reading-actions">${done?`<span class="read-link disabled">Leer ahora ${icon('arrow')}</span>`:`<a class="read-link" href="${escape(bibleUrl(r,state.version))}" data-action="read" data-date="${day.date}" data-index="${i}" rel="noopener noreferrer">Leer ahora ${icon('arrow')}</a>`}<button class="overflow" data-action="versions" data-date="${day.date}" data-index="${i}" aria-label="Elegir traducción para ${escape(readingLabel(r))}">⋮</button></div></article>`;}).join('')}</div><p class="connection">${icon('spark')}${escape(day.connection)}</p></section>`;}
function dayView(){const p=state.plan,idx=p.days.findIndex(d=>d.date===state.date),selected=idx>=0?p.days[idx]:p.days[0],actual=idx>=0?idx:0,pr=progress(),image=state.background?`with-image`:'';return `<div class="layout"><div class="column"><section class="hero ${image}" ${image?`style="background-image:url('./images/theme_${p.theme}${state.variant?'_alt'+(state.variant===2?'2':''):''}.webp')"`:''}><div><span class="eyebrow">${state.date===today()?'HOY':'TU RECORRIDO'} · DÍA ${actual+1} DE ${p.days.length}</span><h1>${escape(dateLong(selected.date))}</h1><p class="quiet">${escape(titleTheme(p.theme))}</p></div><div class="hero-meta"><span>${escape(p.preferences?`${p.preferences.weekdayChapters} entre semana · ${p.preferences.weekendChapters} fin de semana`:'Plan de lectura')}</span><div class="day-switch"><button data-action="prev-day" ${actual===0?'disabled':''} aria-label="Día anterior">${icon('left')}</button><button data-action="next-day" ${actual===p.days.length-1?'disabled':''} aria-label="Día siguiente">${icon('right')}</button></div></div></section>${dayCard(selected)}</div><div class="column side"><section class="card"><div class="progress-line"><span>Mi recorrido</span><span>${pr.percent}%</span></div><progress value="${pr.done}" max="${pr.total}"></progress><div class="progress-details"><span>${pr.done} de ${pr.total} capítulos</span><span>${pr.complete} días completos</span></div></section><section class="card flat download-area"><h3>Tu plan contigo</h3><p class="quiet">Descarga 40 días en PDF o guarda un respaldo con todo tu progreso.</p><button class="button secondary full" data-action="pdf">${icon('download')} Descargar próximos 40 días</button><button class="button outline full" data-action="backup">${icon('share')} Guardar plan .senda</button></section></div></div>`;}
function calendarDays(month){const [y,m]=month.split('-').map(Number),count=new Date(Date.UTC(y,m,0)).getUTCDate(),offset=(new Date(Date.UTC(y,m-1,1)).getUTCDay()+6)%7;return Array.from({length:offset},()=>null).concat(Array.from({length:count},(_,i)=>`${month}-${String(i+1).padStart(2,'0')}`));}
function calendarCard(){
 const days=calendarDays(state.month),plan=state.plan;
 return `<section class="card flat"><div class="month-toolbar"><button data-action="prev-month" aria-label="Mes anterior" ${state.month<=plan.startDate.slice(0,7)?'disabled':''}>${icon('left')}</button><h3>${escape(nameMonth(state.month))}</h3><button data-action="next-month" aria-label="Mes siguiente" ${state.month>=plan.days.at(-1).date.slice(0,7)?'disabled':''}>${icon('right')}</button></div><div class="month-grid">${['L','M','M','J','V','S','D'].map(x=>`<span class="weekday">${x}</span>`).join('')}${days.map(date=>{
  if(!date)return '<span></span>';
  const day=planDay(date),valid=!!day,canMark=valid&&date<=today(),picked=state.selectingDays&&state.selectedDates.has(date);
  const status=valid?(readStatus(day)==='complete'?'completo':readStatus(day)==='partial'?'parcial':'sin leer'):'fuera del plan';
  const unavailable=state.selectingDays&&!canMark;
  return `<button class="cal-day ${valid?readStatus(day):'outside'} ${unavailable&&valid?'future':''} ${picked?'picked':!state.selectingDays&&state.date===date?'selected':''}" data-action="${state.selectingDays?'toggle-day-select':'select-day'}" data-date="${date}" ${!valid||unavailable?'disabled':''} ${state.selectingDays&&canMark?`aria-pressed="${picked}"`:''} aria-label="${escape(dateLong(date))} · ${status}${unavailable&&valid?' · fecha futura, no se puede registrar aún':''}${picked?' · seleccionado':''}">${+date.slice(-2)}</button>`;
 }).join('')}</div><div class="legend"><span class="complete">Completo</span><span class="partial">Parcial</span><span>Sin leer</span></div></section>`;
}
function monthView(){
 const p=state.plan,count=state.selectedDates.size;
 const selected=[...state.selectedDates].map(planDay).filter(day=>day&&day.date<=today());
 const canComplete=selected.some(day=>readStatus(day)!=='complete');
 const canPartial=selected.some(day=>readStatus(day)==='none'&&day.readings.length>1);
 return `<section class="month-page"><div class="months-head"><div><span class="eyebrow">CALENDARIO</span><h1>Tu recorrido, día a día.</h1><p class="quiet">${escape(dateShort(p.startDate))} — ${escape(dateShort(p.days.at(-1).date))}</p></div><button class="button outline" data-action="go-today">Hoy</button></div><div class="month-selection-bar"><button class="button outline" data-action="select-days">${state.selectingDays?'Cancelar selección':'Seleccionar días'}</button>${state.selectingDays?`<span class="quiet" role="status">${count} ${count===1?'día seleccionado':'días seleccionados'}</span><button class="button primary" data-action="complete-days" ${canComplete?'':'disabled'}>${icon('check')} Marcar completos</button><button class="button secondary" data-action="partial-days" ${canPartial?'':'disabled'}>Marcar parciales</button>`:''}</div>${calendarCard()}<p class="month-summary">${state.selectingDays?'Selecciona días hasta hoy, incluso de otros meses. La marca parcial registra un capítulo en cada día no leído que tenga al menos dos; no borra lecturas previas.':'Toca un día del plan para ver sus lecturas.'} Verde indica completo, amarillo parcial y rojo sin leer; los días fuera del plan están atenuados.</p></section>`;
}
function installHelpLabel(){return document.documentElement.dataset.platform==='windows'?'Cómo instalar en Windows':document.documentElement.dataset.platform==='apple'?'Cómo instalar en iPhone, iPad o Mac':'Cómo instalar Senda';}
function advanced(){const p=state.plan,pr=progress();return `<section class="settings-stack"><div><span class="eyebrow">PERSONALIZA TU EXPERIENCIA</span><h1>Avanzado</h1><p class="quiet">Tu apariencia y tus lecturas, en un solo lugar.</p></div><section class="card"><h2>Apariencia</h2><div class="setting-grid"><div>${selectField('mode','Tema',state.mode,[['system','Automático'],['light','Claro'],['dark','Oscuro']])}</div><div>${selectField('version','Traducción predeterminada',state.version,Object.entries(VERSIONS).map(([id,[name]])=>[id,`${id==='CUSTOM'?'':id+' · '}${name}`]))}</div></div><h3>Color de énfasis</h3><div class="color-grid">${Object.entries(ACCENTS).map(([id,[name,color]])=>`<button class="color-choice ${state.accent===id?'active':''}" data-action="accent" data-value="${id}" aria-pressed="${state.accent===id}"><span class="swatch" style="background:${color}"></span>${name}</button>`).join('')}</div><h3 class="group-title">Tamaño de letra</h3><div class="segmented" role="group" aria-label="Tamaño de letra"><button data-action="size" data-value="normal" class="${state.size==='normal'?'active':''}">Normal</button><button data-action="size" data-value="large" class="${state.size==='large'?'active':''}">Grande</button></div>${toggleField('background','Fondo dinámico','Opcional: Habilita está opción para ver una imagen inspirada en el tema de tu plan.',state.background)}${state.background?`<button class="button ghost" data-action="renew">${icon('spark')} Renovar imagen</button>`:''}</section><section class="card"><h2>Tu progreso</h2><div class="progress-line"><span>Capítulos completados</span><span>${pr.percent}%</span></div><progress value="${pr.done}" max="${pr.total}"></progress><div class="stat-grid" style="margin-top:1rem"><div class="stat"><b>${pr.complete}</b><span>Días completos</span></div><div class="stat"><b>${pr.partial}</b><span>Días parciales</span></div><div class="stat"><b>${pr.complete+pr.partial}</b><span>Días leídos</span></div><div class="stat"><b>${pr.unread}</b><span>Días sin leer</span></div></div></section><section class="card"><h2>Guardar y llevar</h2><p class="quiet">Tu plan y progreso se guardan aquí sin cuenta ni contraseña. Para otro dispositivo, exporta e importa un respaldo.</p><div class="button-row"><button class="button secondary" data-action="backup">${icon('share')} Guardar plan .senda</button><label class="button outline file-button">${icon('download')} Restaurar .senda<input type="file" accept=".senda,application/vnd.senda.plan" data-action="import" aria-label="Restaurar respaldo .senda"></label><button class="button outline" data-action="pdf">${icon('download')} PDF · próximos 40 días</button></div></section><section class="card flat"><h2>Opciones del plan</h2><p class="quiet">Crear un plan nuevo reemplaza el actual y reinicia sus estadísticas.</p><button class="button outline" data-action="confirm-new">Generar otro plan</button></section><section class="card flat"><h2>Acerca de Senda</h2><p class="quiet">Web App 1.0<br>Desarrollada por jucenm.</p><button class="button ghost" data-action="show-install">${installHelpLabel()} ${icon('arrow')}</button></section></section>`;}
 function dialog(){if(!state.dialog)return '';const d=state.dialog;if(d.type==='versions'){const day=planDay(d.date),r=day?.readings[d.index];if(!r)return '';const versions=bookById[r.book]?.dc?{TLAI:VERSIONS.TLAI}:VERSIONS;return `<div class="dialog-backdrop"><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">¿En qué versión deseas leer esta lectura?</h2><p>${escape(readingLabel(r))}</p>${Object.entries(versions).map(([id,[name]])=>`<a class="button outline full" href="${escape(bibleUrl(r,id))}" data-action="read" data-date="${d.date}" data-index="${d.index}" data-version="${id}" rel="noopener noreferrer">${id==='CUSTOM'?'':id+' · '}${escape(name)} ${icon('arrow')}</a>`).join('')}<button class="button ghost" data-action="close-dialog">Cerrar</button></div></div>`;}
 if(d.type==='reread')return `<div class="dialog-backdrop"><div class="dialog" role="alertdialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">Lectura completada</h2><p>Esta lectura ha sido completada. ¿Estás seguro(a) de que quieres volver a leer este capítulo?</p><button class="button primary" data-action="uncomplete">Sí, leer nuevamente</button><button class="button outline" data-action="close-dialog">Ya he leído</button></div></div>`;
 if(d.type==='complete-days'){
  const days=[...state.selectedDates].map(planDay).filter(day=>day&&day.date<=today());
  const partial=d.mode==='partial';
  const affected=partial?days.filter(day=>readStatus(day)==='none'&&day.readings.length>1):days.filter(day=>readStatus(day)!=='complete');
  const pending=affected.reduce((total,day)=>total+day.readings.filter((_,i)=>!state.completed.has(completionKey(day.date,i))).length,0);
  const detail=partial?`${affected.length===1?'Se marcará un capítulo del día seleccionado':'Se marcará un capítulo de cada uno de los '+affected.length+' días seleccionados'} con al menos dos lecturas y sin progreso previo. Los días ya parciales o completos no cambiarán.`:`Se marcarán como leídos ${pending} ${pending===1?'capítulo pendiente':'capítulos pendientes'} de ${affected.length} ${affected.length===1?'día':'días'}.`;
  return `<div class="dialog-backdrop"><div class="dialog" role="alertdialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${partial?'Marcar lectura parcial':'Completar días seleccionados'}</h2><p>${detail} El progreso y el calendario se actualizarán.</p><button class="button primary" data-action="confirm-complete-days">${partial?'Sí, marcar parciales':'Sí, marcar completos'}</button><button class="button outline" data-action="close-dialog">Cancelar</button></div></div>`;
 }
 if(d.type==='new')return `<div class="dialog-backdrop"><div class="dialog" role="alertdialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">¿Crear un nuevo plan?</h2><p>Se reemplazará tu plan actual y se reiniciará el progreso. Puedes guardar antes una copia .senda.</p><button class="button secondary" data-action="backup">Guardar plan antes</button><button class="button primary" data-action="new-plan">Crear plan nuevo</button><button class="button outline" data-action="close-dialog">Conservar mi plan</button></div></div>`;
 if(d.type==='install'){
  const platform=document.documentElement.dataset.platform;
  const instructions=platform==='windows'
   ?'<p>En Microsoft Edge, usa el icono de instalación de la barra de direcciones o abre el menú <strong>⋯ → Más herramientas → Aplicaciones → Instalar este sitio como aplicación</strong>.</p><p>En Chrome, busca <strong>Instalar página como aplicación</strong> en el menú o usa el icono de instalación de la barra de direcciones.</p>'
   :platform==='apple'
    ?'<p>En iPhone o iPad: abre esta página en Safari, toca Compartir y elige <strong>Añadir a pantalla de inicio</strong>.</p><p>En Mac: abre esta página en Safari y selecciona <strong>Archivo → Añadir al Dock</strong>. En otros navegadores busca “Instalar aplicación” en el menú.</p>'
    :'<p>Busca la opción <strong>Instalar aplicación</strong> o <strong>Añadir a pantalla de inicio</strong> en el menú de tu navegador.</p>';
  return `<div class="dialog-backdrop"><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">Instalar Senda</h2>${instructions}<p>Antes de instalarla o cambiar de dispositivo, guarda una copia <strong>.senda</strong> de tu plan. Puedes restaurarla desde Avanzado si el almacenamiento no se comparte con la app instalada.</p><p>El plan queda disponible sin conexión después de abrir la app instalada. YouVersion requiere conexión para abrir lecturas que no hayas descargado allí.</p><button class="button primary" data-action="close-dialog">Entendido</button></div></div>`;
 }
 if(d.type==='pdf')return `<div class="dialog-backdrop"><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">Tu PDF está listo</h2><p>Se prepararon ${d.days} días desde ${escape(dateShort(d.start))}. La descarga se ha solicitado al navegador.</p><a class="button primary" href="${escape(d.url)}" download="${escape(d.name)}">${icon('download')} Volver a descargar PDF</a><a class="button outline" href="${escape(d.url.startsWith('/')?d.url+'?preview=1':d.url)}" target="_blank" rel="noopener noreferrer">${icon('book')} Abrir PDF</a>${navigator.share&&navigator.canShare?'<button class="button outline" data-action="share-pdf">Compartir o guardar en Archivos</button>':''}<p class="hint">Revisa las descargas del navegador. Si usas un navegador integrado que no permite guardar el archivo, abre Senda en Safari o Chrome.</p><button class="button ghost" data-action="close-dialog">Cerrar</button></div></div>`;
 return '';
}
function closeDialog(){if(state.dialog?.type==='pdf')URL.revokeObjectURL(state.dialog.blobUrl);state.dialog=null;render();}
function render(){applyAppearance();const app=document.getElementById('app');const expired=state.plan&&today()>state.plan.days.at(-1).date;if(expired){state.tab='day';}app.innerHTML=shell(!state.plan||expired?onboarding():state.tab==='month'?monthView():state.tab==='advanced'?advanced():dayView());}
function setPlan(plan,completed=new Set()){validatePlan(plan);state.plan=plan;state.completed=completed;state.selectingDays=false;state.selectedDates.clear();state.date=today()>=plan.startDate&&today()<=plan.days.at(-1).date?today():plan.startDate;state.month=state.date.slice(0,7);state.tab='day';state.dialog=null;state.error='';persist();render();}
function handleField(input){const id=input.dataset.field;if(!id)return;if(!state.plan||today()>state.plan.days.at(-1).date){if(id in draft){draft[id]=input.type==='checkbox'?input.checked:input.type==='range'||id==='proverbCycles'?+input.value:input.value;render();return;}}if(id==='version'){state.version=input.value;}else if(id==='mode'){state.mode=input.value;}else if(id==='background'){state.background=input.checked;}else return;persist();render();}
document.addEventListener('input',event=>{const el=event.target;if(el.type==='range'&&el.dataset.field){document.getElementById(el.id+'-value').textContent=el.value;}});
document.addEventListener('change',async event=>{const el=event.target;if(el.dataset.action==='import'){const file=el.files?.[0];if(!file)return;try{const backup=await importBackup(file);state.version=VERSIONS[backup.bibleVersion]?backup.bibleVersion:'RVC';setPlan(backup.plan,backup.completed);message('Plan y progreso restaurados.');}catch(error){message(error.message||'No se pudo restaurar el respaldo.');}return;}handleField(el);});
document.addEventListener('submit',async event=>{if(event.target.id!=='new-plan')return;event.preventDefault();if(state.generating)return;state.generating=true;state.error='';render();try{const p=await generatePlanAsync(today(),draft.theme,draft.dc,{weekdayChapters:draft.weekdayChapters,weekendChapters:draft.weekendChapters,repeatPsalms:draft.repeatPsalms,proverbCycles:draft.proverbCycles,repeatGospels:draft.repeatGospels});setPlan(p);message('Tu plan está listo.');}catch(error){state.error=error.message;render();}finally{state.generating=false;render();}});
document.addEventListener('click',async event=>{if(!event.target.closest('[data-action="share-pdf"]')||state.dialog?.type!=='pdf')return;const d=state.dialog;try{const data=createPlanPdf(state.plan,d.start,state.size==='large',ACCENTS[state.accent][1]);const file=new File([data],d.name,{type:'application/pdf'});if(!navigator.canShare({files:[file]}))throw Error('Este navegador no admite compartir archivos.');await navigator.share({files:[file]});}catch(error){if(error.name!=='AbortError')message(error.message||'No se pudo compartir el PDF.');}});
document.addEventListener('click',event=>{
 const target=event.target.closest('[data-tab],[data-action]');
 if(!target)return;
 if((target.dataset.tab&&target.dataset.tab!=='month')||['go-today','new-plan'].includes(target.dataset.action)){
  state.selectingDays=false;state.selectedDates.clear();return;
 }
 const action=target.dataset.action;
 if(!['select-days','toggle-day-select','complete-days','partial-days','confirm-complete-days'].includes(action))return;
 event.stopImmediatePropagation();
 if(action==='select-days'){state.selectingDays=!state.selectingDays;state.selectedDates.clear();render();return;}
 if(action==='toggle-day-select'){
  const date=target.dataset.date;
  if(!state.selectingDays||!planDay(date)||date>today())return;
  state.selectedDates.has(date)?state.selectedDates.delete(date):state.selectedDates.add(date);
  render();return;
 }
 if(!state.selectingDays||!state.selectedDates.size)return;
 if(action==='complete-days'||action==='partial-days'){
  state.dialog={type:'complete-days',mode:action==='partial-days'?'partial':'complete'};render();return;
 }
 if(state.dialog?.type!=='complete-days')return;
 const days=[...state.selectedDates].map(planDay).filter(day=>day&&day.date<=today());
 const partial=state.dialog?.type==='complete-days'&&state.dialog.mode==='partial';
 const affected=partial?days.filter(day=>readStatus(day)==='none'&&day.readings.length>1):days.filter(day=>readStatus(day)!=='complete');
 if(!affected.length){state.dialog=null;render();return;}
 for(const day of affected){
  if(partial){const first=day.readings.findIndex((_,i)=>!state.completed.has(completionKey(day.date,i)));if(first>=0)state.completed.add(completionKey(day.date,first));}
  else day.readings.forEach((_,i)=>state.completed.add(completionKey(day.date,i)));
 }
 state.selectingDays=false;state.selectedDates.clear();state.dialog=null;
 const result=partial?affected.length===1?'día marcado como parcial':'días marcados como parciales':affected.length===1?'día completado':'días completados';
 if(persist())message(`${affected.length} ${result}.`);
});
document.addEventListener('click',async event=>{const target=event.target.closest('[data-tab],[data-action]');if(!target)return;if(target.dataset.tab){state.tab=target.dataset.tab;if(state.plan&&state.tab==='day'&&today()>=state.plan.startDate&&today()<=state.plan.days.at(-1).date)state.date=today();render();return;}const act=target.dataset.action,date=target.dataset.date,index=+target.dataset.index;if(act==='read'){openYouVersionOnApple(event,target,date,index);state.completed.add(completionKey(date,index));persist();state.dialog=null;setTimeout(render,0);return;}if(act==='versions'){state.dialog={type:'versions',date,index};render();return;}if(act==='toggle-reading'){if(state.completed.has(completionKey(date,index))){state.dialog={type:'reread',date,index};render();}else{state.completed.add(completionKey(date,index));persist();render();}return;}if(act==='uncomplete'){state.completed.delete(completionKey(state.dialog.date,state.dialog.index));state.dialog=null;persist();render();return;}if(act==='close-dialog'){closeDialog();return;}if(act==='prev-day'||act==='next-day'){const i=state.plan.days.findIndex(d=>d.date===state.date)+(act==='next-day'?1:-1);if(state.plan.days[i]){state.date=state.plan.days[i].date;state.month=state.date.slice(0,7);render();}return;}if(act==='prev-month'||act==='next-month'){state.month=monthOffset(state.month,act==='next-month'?1:-1);render();return;}if(act==='select-day'){state.date=date;state.month=date.slice(0,7);state.tab='day';render();return;}if(act==='go-today'){state.date=today()>=state.plan.startDate&&today()<=state.plan.days.at(-1).date?today():state.plan.startDate;state.month=state.date.slice(0,7);state.tab='day';render();return;}if(act==='accent'){state.accent=target.dataset.value;persist();render();return;}if(act==='size'){state.size=target.dataset.value;persist();render();return;}if(act==='renew'){state.variant=(state.variant+1)%3;persist();render();return;}if(act==='confirm-new'){state.dialog={type:'new'};render();return;}if(act==='new-plan'){state.dialog=null;state.plan=null;state.completed.clear();persist();render();return;}if(act==='show-install'){state.dialog={type:'install'};render();return;}if(act==='backup'){try{await exportBackup(state.plan,state.completed,state.version);message('Respaldo .senda descargado.');}catch(error){message(error.message||'No se pudo guardar el respaldo.');}return;}if(act==='pdf'){try{const start=today()<state.plan.startDate?state.plan.startDate:today();const prepared=preparePdf(state.plan,start,state.size==='large',ACCENTS[state.accent][1]);downloadBytes(prepared.data,prepared.name,'application/pdf');const downloadUrl=await cachePdfForDownload(prepared.data,prepared.name);state.dialog={type:'pdf',start,url:downloadUrl||prepared.url,blobUrl:prepared.url,name:prepared.name,days:prepared.days};render();}catch(error){message(error.message||'No se pudo crear el PDF.');}return;}});
window.addEventListener('focus',()=>{const t=today();if(state.plan&&state.tab==='day'&&state.date!==t&&t>=state.plan.startDate&&t<=state.plan.days.at(-1).date){state.date=t;state.month=t.slice(0,7);render();}});
setInterval(()=>{const t=today();if(state.plan&&state.tab==='day'&&state.date!==t&&t>=state.plan.startDate&&t<=state.plan.days.at(-1).date){state.date=t;state.month=t.slice(0,7);render();}},60000);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.dialog)closeDialog();});
const modelContext=document.modelContext;
if(modelContext?.registerTool){
  Promise.resolve(modelContext.registerTool({name:'consultar_progreso_senda',title:'Consultar progreso de Senda',description:'Consultar el progreso del plan de lectura guardado en este navegador.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){if(!state.plan)return {plan:null};const p=progress();return {inicio:state.plan.startDate,fin:state.plan.days.at(-1).date,capitulosLeidos:p.done,capitulosTotales:p.total,diasCompletos:p.complete};}})).catch(()=>{});
  Promise.resolve(modelContext.registerTool({name:'marcar_lectura_senda',title:'Marcar lectura de Senda',description:'Marcar como completado un capítulo del plan guardado en este navegador.',inputSchema:{type:'object',properties:{fecha:{type:'string',description:'Fecha ISO YYYY-MM-DD'},indice:{type:'integer',minimum:0}},required:['fecha','indice'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const {fecha,indice}=input||{};const day=planDay(fecha);if(!day||!Number.isInteger(indice)||indice<0||indice>=day.readings.length)throw Error('La lectura indicada no pertenece al plan.');state.completed.add(completionKey(fecha,indice));persist();render();return {fecha,indice,completada:true};}})).catch(()=>{});
}
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
render();
